(()=>{'use strict';const configs=new Map(BloomScreenConfig.map(x=>[x.id,x])),instances=new Map();let helpController=null;function openHelp(c){if(window.omniMediaController!==helpController){BloomUI.addHelp({title:c.title,container:document.createElement('div')});helpController=window.omniMediaController}BloomUI.help({title:c.title})}const make=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';if(text)e.textContent=text;return e};function ensure(id){if(instances.has(id))return instances.get(id);const c=configs.get(id);if(!c||c.native)throw Error('SCREEN_NOT_WEB');if(document.documentElement.dataset.bloomSource!==c.source)throw Error('WRONG_SOURCE');const root=document.querySelector(c.selector);if(!root)throw Error('SCREEN_ROOT_MISSING');const region=c.contentSelector?document.querySelector(c.contentSelector):null,panel=make('section','bloom-screen-state'),heading=make('h2'),body=make('p'),action=make('button'),skeleton=make('div','bloom-screen-skeleton');panel.dataset.screen=id;panel.hidden=true;panel.setAttribute('role','status');action.type='button';skeleton.setAttribute('aria-hidden','true');for(let i=0;i<3;i++)skeleton.append(make('span'));panel.append(heading,body,skeleton,action);const anchor=region?.closest('table')||region;if(anchor&&root.contains(anchor))anchor.before(panel);else{const title=root.querySelector('h1,h2');if(title&&title.parentElement===root)title.after(panel);else root.prepend(panel)}const record={c,root,region,panel,heading,body,action,skeleton,originalHidden:region?.hidden||false,originalBusy:root.getAttribute('aria-busy'),state:'full'};action.onclick=()=>{const a=c.actions[record.state];if(a?.help){openHelp(c);return}const target=a?.selector?document.querySelector(a.selector):null;if(!target||target.disabled||!target.getClientRects().length){openHelp(c);return}target.focus();target.click()};instances.set(id,record);return record}
function show(id,state,{retain=true,focus=false}={}){const c=configs.get(id);if(!c||!c.states[state]?.applicable)throw Error('STATE_NOT_APPLICABLE');const r=ensure(id);window.BloomLayoutSkeleton?.before(r);r.state=state;r.panel.dataset.state=state;if(state==='full'){r.panel.hidden=true;if(r.region)r.region.hidden=r.originalHidden;if(r.originalBusy===null)r.root.removeAttribute('aria-busy');else r.root.setAttribute('aria-busy',r.originalBusy);return}const copy=c.copy[state];r.heading.textContent=copy.title;r.body.textContent=copy.body;r.panel.hidden=false;r.root.setAttribute('aria-busy',String(state==='loading'||state==='partial'));r.skeleton.hidden=state!=='loading'||retain||!r.region;r.action.hidden=!c.actions[state];r.action.textContent=c.actions[state]?.label||'';if(r.region)r.region.hidden=!retain&&['loading','empty','first-run'].includes(state);if(focus&&!r.action.hidden)r.action.focus();window.BloomLayoutSkeleton?.after(r,state,retain)}
function request(id,run,classify){const r=ensure(id),epoch=(r.epoch||0)+1;r.epoch=epoch;show(id,r.c.states.partial.applicable&&r.hasData?'partial':'loading',{retain:!!r.hasData});return Promise.resolve().then(run).then(value=>{if(r.epoch!==epoch)return value;const state=classify(value);if(!['empty','full','partial'].includes(state))throw Error('INVALID_CLASSIFICATION');r.hasData=state!=='empty';show(id,state,{retain:r.hasData});return value}).catch(error=>{if(r.epoch===epoch){const code=error?.code||error?.message;const state=code==='DENIED'?'permission-denied':code==='OFFLINE'&&r.c.states.offline.applicable?'offline':'error';show(id,state,{retain:!!r.hasData})}throw error})}
function reset(id){const r=instances.get(id);if(!r)return;r.epoch=(r.epoch||0)+1;show(id,'full');r.panel.remove();instances.delete(id)}window.BloomScreenStates=Object.freeze({show,request,reset,config:id=>configs.get(id),ids:()=>[...configs.keys()]});})();
